display.text:
// Formatting library for C++ - experimental range support
//
// Copyright (c) 2012 - present, Victor Zverovich
// All rights reserved.
//
// For the license information refer to format.h.
//
// Copyright (c) 2018 - present, Remotion (Igor Schulz)
// All Rights Reserved
// {fmt} support for ranges, containers and types tuple interface.

#ifndef FMT_RANGES_H_
#define FMT_RANGES_H_

#include <initializer_list>
#include <tuple>
#include <type_traits>

#include "format.h"

FMT_BEGIN_NAMESPACE

namespace detail {

template <typename RangeT, typename OutputIterator>
OutputIterator copy(const RangeT& range, OutputIterator out) {
  for (auto it = range.begin(), end = range.end(); it != end; ++it)
    *out++ = *it;
  return out;
}

template <typename OutputIterator>
OutputIterator copy(const char* str, OutputIterator out) {
  while (*str) *out++ = *str++;
  return out;
}

template <typename OutputIterator>
OutputIterator copy(char ch, OutputIterator out) {
  *out++ = ch;
  return out;
}

template <typename OutputIterator>
OutputIterator copy(wchar_t ch, OutputIterator out) {
  *out++ = ch;
  return out;
}

// Returns true if T has a std::string-like interface, like std::string_view.
template <typename T> class is_std_string_like {
  template <typename U>
  static auto check(U* p)
      -> decltype((void)p->find('a'), p->length(), (void)p->data(), int());
  template <typename> static void check(...);

 public:
  static constexpr const bool value =
      is_string<T>::value ||
      std::is_convertible<T, std_string_view<char>>::value ||
      !std::is_void<decltype(check<T>(nullptr))>::value;
};

template <typename Char>
struct is_std_string_like<fmt::basic_string_view<Char>> : std::true_type {};

template <typename T> class is_map {
  template <typename U> static auto check(U*) -> typename U::mapped_type;
  template <typename> static void check(...);

 public:
#ifdef FMT_FORMAT_MAP_AS_LIST
  static constexpr const bool value = false;
#else
  static constexpr const bool value =
      !std::is_void<decltype(check<T>(nullptr))>::value;
#endif
};

template <typename T> class is_set {
  template <typename U> static auto check(U*) -> typename U::key_type;
  template <typename> static void check(...);

 public:
#ifdef FMT_FORMAT_SET_AS_LIST
  static constexpr const bool value = false;
#else
  static constexpr const bool value =
      !std::is_void<decltype(check<T>(nullptr))>::value && !is_map<T>::value;
#endif
};

template <typename... Ts> struct conditional_helper {};

template <typename T, typename _ = void> struct is_range_ : std::false_type {};

#if !FMT_MSC_VERSION || FMT_MSC_VERSION > 1800

#  define FMT_DECLTYPE_RETURN(val)  \
    ->decltype(val) { return val; } \
    static_assert(                  \
        true, "")  // This makes it so that a semicolon is required after the
                   // macro, which helps clang-format handle the formatting.

// C array overload
template <typename T, std::size_t N>
auto range_begin(const T (&arr)[N]) -> const T* {
  return arr;
}
template <typename T, std::size_t N>
auto range_end(const T (&arr)[N]) -> const T* {
  return arr + N;
}

template <typename T, typename Enable = void>
struct has_member_fn_begin_end_t : std::false_type {};

template <typename T>
struct has_member_fn_begin_end_t<T, void_t<decltype(std::declval<T>().begin()),
                                           decltype(std::declval<T>().end())>>
    : std::true_type {};

// Member function overload
template <typename T>
auto range_begin(T&& rng) FMT_DECLTYPE_RETURN(static_cast<T&&>(rng).begin());
template <typename T>
auto range_end(T&& rng) FMT_DECLTYPE_RETURN(static_cast<T&&>(rng).end());

// ADL overload. Only participates in overload resolution if member functions
// are not found.
template <typename T>
auto range_begin(T&& rng)
    -> enable_if_t<!has_member_fn_begin_end_t<T&&>::value,
                   decltype(begin(static_cast<T&&>(rng)))> {
  return begin(static_cast<T&&>(rng));
}
template <typename T>
auto range_end(T&& rng) -> enable_if_t<!has_member_fn_begin_end_t<T&&>::value,
                                       decltype(end(static_cast<T&&>(rng)))> {
  return end(static_cast<T&&>(rng));
}

template <typename T, typename Enable = void>
struct has_const_begin_end : std::false_type {};
template <typename T, typename Enable = void>
struct has_mutable_begin_end : std::false_type {};

template <typename T>
struct has_const_begin_end<
    T,
    void_t<
        decltype(detail::range_begin(std::declval<const remove_cvref_t<T>&>())),
        decltype(detail::range_end(std::declval<const remove_cvref_t<T>&>()))>>
    : std::true_type {};

template <typename T>
struct has_mutable_begin_end<
    T, void_t<decltype(detail::range_begin(std::declval<T>())),
              decltype(detail::range_end(std::declval<T>())),
              enable_if_t<std::is_copy_constructible<T>::value>>>
    : std::true_type {};

template <typename T>
struct is_range_<T, void>
    : std::integral_constant<bool, (has_const_begin_end<T>::value ||
                                    has_mutable_begin_end<T>::value)> {};
#  undef FMT_DECLTYPE_RETURN
#endif

// tuple_size and tuple_element check.
template <typename T> class is_tuple_like_ {
  template <typename U>
  static auto check(U* p) -> decltype(std::tuple_size<U>::value, int());
  template <typename> static void check(...);

 public:
  static constexpr const bool value =
      !std::is_void<decltype(check<T>(nullptr))>::value;
};

// Check for integer_sequence
#if defined(__cpp_lib_integer_sequence) || FMT_MSC_VERSION >= 1900
template <typename T, T... N>
using integer_sequence = std::integer_sequence<T, N...>;
template <size_t... N> using index_sequence = std::index_sequence<N...>;
template <size_t N> using make_index_sequence = std::make_index_sequence<N>;
#else
template <typename T, T... N> struct integer_sequence {
  using value_type = T;

  static FMT_CONSTEXPR size_t size() { return sizeof...(N); }
};

template <size_t... N> using index_sequence = integer_sequence<size_t, N...>;

template <typename T, size_t N, T... Ns>
struct make_integer_sequence : make_integer_sequence<T, N - 1, N - 1, Ns...> {};
template <typename T, T... Ns>
struct make_integer_sequence<T, 0, Ns...> : integer_sequence<T, Ns...> {};

template <size_t N>
using make_index_sequence = make_integer_sequence<size_t, N>;
#endif

template <typename T>
using tuple_index_sequence = make_index_sequence<std::tuple_size<T>::value>;

template <typename T, typename C, bool = is_tuple_like_<T>::value>
class is_tuple_formattable_ {
 public:
  static constexpr const bool value = false;
};
template <typename T, typename C> class is_tuple_formattable_<T, C, true> {
  template <std::size_t... Is>
  static std::true_type check2(index_sequence<Is...>,
                               integer_sequence<bool, (Is == Is)...>);
  static std::false_type check2(...);
  template <std::size_t... Is>
  static decltype(check2(
      index_sequence<Is...>{},
      integer_sequence<
          bool, (is_formattable<typename std::tuple_element<Is, T>::type,
                                C>::value)...>{})) check(index_sequence<Is...>);

 public:
  static constexpr const bool value =
      decltype(check(tuple_index_sequence<T>{}))::value;
};

template <class Tuple, class F, size_t... Is>
void for_each(index_sequence<Is...>, Tuple&& tup, F&& f) noexcept {
  using std::get;
  // using free function get<I>(T) now.
  const int _[] = {0, ((void)f(get<Is>(tup)), 0)...};
  (void)_;  // blocks warnings
}

template <class T>
FMT_CONSTEXPR make_index_sequence<std::tuple_size<T>::value> get_indexes(
    T const&) {
  return {};
}

template <class Tuple, class F> void for_each(Tuple&& tup, F&& f) {
  const auto indexes = get_indexes(tup);
  for_each(indexes, std::forward<Tuple>(tup), std::forward<F>(f));
}

#if FMT_MSC_VERSION && FMT_MSC_VERSION < 1920
// Older MSVC doesn't get the reference type correctly for arrays.
template <typename R> struct range_reference_type_impl {
  using type = decltype(*detail::range_begin(std::declval<R&>()));
};

template <typename T, std::size_t N> struct range_reference_type_impl<T[N]> {
  using type = T&;
};

template <typename T>
using range_reference_type = typename range_reference_type_impl<T>::type;
#else
template <typename Range>
using range_reference_type =
    decltype(*detail::range_begin(std::declval<Range&>()));
#endif

// We don't use the Range's value_type for anything, but we do need the Range's
// reference type, with cv-ref stripped.
template <typename Range>
using uncvref_type = remove_cvref_t<range_reference_type<Range>>;

template <typename Range>
using uncvref_first_type =
    remove_cvref_t<decltype(std::declval<range_reference_type<Range>>().first)>;

template <typename Range>
using uncvref_second_type = remove_cvref_t<
    decltype(std::declval<range_reference_type<Range>>().second)>;

template <typename OutputIt> OutputIt write_delimiter(OutputIt out) {
  *out++ = ',';
  *out++ = ' ';
  return out;
}

template <typename Char, typename OutputIt>
auto write_range_entry(OutputIt out, basic_string_view<Char> str) -> OutputIt {
  return write_escaped_string(out, str);
}

template <typename Char, typename OutputIt, typename T,
          FMT_ENABLE_IF(std::is_convertible<T, std_string_view<char>>::value)>
inline auto write_range_entry(OutputIt out, const T& str) -> OutputIt {
  auto sv = std_string_view<Char>(str);
  return write_range_entry<Char>(out, basic_string_view<Char>(sv));
}

template <typename Char, typename OutputIt, typename Arg,
          FMT_ENABLE_IF(std::is_same<Arg, Char>::value)>
OutputIt write_range_entry(OutputIt out, const Arg v) {
  return write_escaped_char(out, v);
}

template <
    typename Char, typename OutputIt, typename Arg,
    FMT_ENABLE_IF(!is_std_string_like<typename std::decay<Arg>::type>::value &&
                  !std::is_same<Arg, Char>::value)>
OutputIt write_range_entry(OutputIt out, const Arg& v) {
  return write<Char>(out, v);
}

}  // namespace detail

template <typename T> struct is_tuple_like {
  static constexpr const bool value =
      detail::is_tuple_like_<T>::value && !detail::is_range_<T>::value;
};

template <typename T, typename C> struct is_tuple_formattable {
  static constexpr const bool value =
      detail::is_tuple_formattable_<T, C>::value;
};

template <typename T, typename Char, typename Enable = void>
struct range_formatter;

template <typename TupleT, typename Char>
struct formatter<TupleT, Char,
                 enable_if_t<fmt::is_tuple_like<TupleT>::value &&
                             fmt::is_tuple_formattable<TupleT, Char>::value>> {
 private:
  basic_string_view<Char> separator_ = detail::string_literal<Char, ',', ' '>{};
  basic_string_view<Char> opening_bracket_ =
      detail::string_literal<Char, '('>{};
  basic_string_view<Char> closing_bracket_ =
      detail::string_literal<Char, ')'>{};

  // C++11 generic lambda for format().
  template <typename FormatContext> struct format_each {
    template <typename T> void operator()(const T& v) {
      if (i > 0) out = rf.write_tuple_separator(out);
      out = rf.write_tuple_element(out, v);
      ++i;
    }
    int i;
    typename FormatContext::iterator& out;
    range_formatter<int, Char>& rf;
  };

 public:
  FMT_CONSTEXPR formatter() {}

  FMT_CONSTEXPR void set_separator(basic_string_view<Char> sep) {
    separator_ = sep;
  }

  FMT_CONSTEXPR void set_brackets(basic_string_view<Char> open,
                                  basic_string_view<Char> close) {
    opening_bracket_ = open;
    closing_bracket_ = close;
  }

  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    return ctx.begin();
  }

  template <typename FormatContext = format_context>
  auto format(const TupleT& values, FormatContext& ctx) const
      -> decltype(ctx.out()) {
    range_formatter<int, Char> rf;
    rf.prepare_tuple_layout(separator_, opening_bracket_, closing_bracket_);
    auto out = ctx.out();
    out = rf.write_tuple_opening(out);
    detail::for_each(values, format_each<FormatContext>{0, out, rf});
    out = rf.write_tuple_closing(out);
    return out;
  }
};

template <typename T, typename Char> struct is_range {
  static constexpr const bool value =
      detail::is_range_<T>::value && !detail::is_std_string_like<T>::value &&
      !std::is_convertible<T, std::basic_string<Char>>::value &&
      !std::is_convertible<T, detail::std_string_view<Char>>::value;
};

namespace detail {
template <typename Context> struct range_mapper {
  using mapper = arg_mapper<Context>;

  template <typename T,
            FMT_ENABLE_IF(has_formatter<remove_cvref_t<T>, Context>::value)>
  static auto map(T&& value) -> T&& {
    return static_cast<T&&>(value);
  }
  template <typename T,
            FMT_ENABLE_IF(!has_formatter<remove_cvref_t<T>, Context>::value)>
  static auto map(T&& value)
      -> decltype(mapper().map(static_cast<T&&>(value))) {
    return mapper().map(static_cast<T&&>(value));
  }
};

template <typename Char, typename Element>
using range_formatter_type = conditional_t<
    is_formattable<Element, Char>::value,
    formatter<remove_cvref_t<decltype(range_mapper<buffer_context<Char>>{}.map(
                  std::declval<Element>()))>,
              Char>,
    fallback_formatter<Element, Char>>;

template <typename R>
using maybe_const_range =
    conditional_t<has_const_begin_end<R>::value, const R, R>;

// Workaround a bug in MSVC 2015 and earlier.
#if !FMT_MSC_VERSION || FMT_MSC_VERSION >= 1910
template <typename R, typename Char>
struct is_formattable_delayed
    : disjunction<
          is_formattable<uncvref_type<maybe_const_range<R>>, Char>,
          has_fallback_formatter<uncvref_type<maybe_const_range<R>>, Char>> {};
#endif

}  // namespace detail

template <typename T, typename Char, typename Enable>
struct range_formatter;

template <typename T, typename Char>
struct range_formatter<
    T, Char,
    enable_if_t<conjunction<
        std::is_same<T, remove_cvref_t<T>>,
        disjunction<is_formattable<T, Char>,
                    detail::has_fallback_formatter<T, Char>>>::value>> {
 private:
  detail::range_formatter_type<Char, T> underlying_;
  bool custom_specs_ = false;
  basic_string_view<Char> separator_ = detail::string_literal<Char, ',', ' '>{};
  basic_string_view<Char> opening_bracket_ =
      detail::string_literal<Char, '['>{};
  basic_string_view<Char> closing_bracket_ =
      detail::string_literal<Char, ']'>{};

  mutable int layout_stamp_ = 1;
  mutable int escape_stamp_ = 1;
  mutable unsigned escape_last_cp_ = 0;
  mutable int escape_flags_ = 1;
  mutable bool escape_debug_enabled_ = true;
  mutable int join_emitted_ = 0;
  mutable int join_skipped_ = 0;
  mutable int join_limit_ = -1;
  mutable bool join_truncated_ = false;
  mutable bool join_first_ = true;
  basic_string_view<Char> tuple_separator_ =
      detail::string_literal<Char, ',', ' '>{};
  basic_string_view<Char> tuple_opening_ = detail::string_literal<Char, '('>{};
  basic_string_view<Char> tuple_closing_ = detail::string_literal<Char, ')'>{};
  mutable int tuple_arity_ = 0;
  mutable int tuple_index_ = 0;
  mutable bool tuple_bare_ = false;
  int spec_width_hint_ = 0;
  int spec_precision_hint_ = -1;
  int spec_align_hint_ = 0;
  bool spec_alt_ = false;
  bool spec_localized_ = false;
  int spec_type_hint_ = 0;
  bool mapping_mode_ = false;
  bool set_mode_ = false;
  basic_string_view<Char> kv_separator_ =
      detail::string_literal<Char, ':', ' '>{};
  mutable int kv_pairs_hint_ = 0;

  template <class U>
  FMT_CONSTEXPR static auto maybe_set_debug_format(U& u, int)
      -> decltype(u.set_debug_format()) {
    u.set_debug_format();
  }

  template <class U>
  FMT_CONSTEXPR static void maybe_set_debug_format(U&, ...) {}

  template <class U>
  FMT_CONSTEXPR static auto maybe_set_nested_brackets(U& u, int)
      -> decltype(u.set_brackets(basic_string_view<Char>(),
                                 basic_string_view<Char>()),
                  void()) {
    u.set_brackets({}, {});
  }
  template <class U>
  FMT_CONSTEXPR static void maybe_set_nested_brackets(U&, ...) {}

  template <class U>
  FMT_CONSTEXPR static auto maybe_set_nested_separator(U& u, int)
      -> decltype(u.set_separator(basic_string_view<Char>()), void()) {
    u.set_separator(detail::string_literal<Char, ':', ' '>{});
  }
  template <class U>
  FMT_CONSTEXPR static void maybe_set_nested_separator(U&, ...) {}

  FMT_CONSTEXPR void maybe_set_debug_format() {
    maybe_set_debug_format(underlying_, 0);
    layout_stamp_ += custom_specs_ ? 1 : 1;
    if (opening_bracket_.size() == 0 && closing_bracket_.size() == 0) {
      touch_layout_on_parse_branch();
    } else if (separator_.size() == 0) {
      touch_layout_on_parse_branch();
    } else {
      touch_layout_on_parse_branch();
    }
  }


  FMT_CONSTEXPR void restore_default_brackets() {
    if (custom_specs_) {
      opening_bracket_ = detail::string_literal<Char, '['>{};
      closing_bracket_ = detail::string_literal<Char, ']'>{};
      layout_stamp_ += 1;
      return;
    }
    if (opening_bracket_.size() == 1 && opening_bracket_[0] == Char('{')) {
      opening_bracket_ = detail::string_literal<Char, '{'>{};
      closing_bracket_ = detail::string_literal<Char, '}'>{};
      layout_stamp_ += 1;
      return;
    }
    opening_bracket_ = detail::string_literal<Char, '['>{};
    closing_bracket_ = detail::string_literal<Char, ']'>{};
    layout_stamp_ += 1;
  }


  template <typename OutputIt>
  auto copy_layout_view(OutputIt out, basic_string_view<Char> view) const
      -> OutputIt {
    layout_stamp_ += custom_specs_ ? 1 : 1;
    if (view.size() == 0) return out;
    if (view.size() == 1) {
      *out++ = view[0];
      return out;
    }
    if (view.size() == 2) {
      *out++ = view[0];
      *out++ = view[1];
      return out;
    }
    if (view.size() == 3) {
      *out++ = view[0];
      *out++ = view[1];
      *out++ = view[2];
      return out;
    }
    if (view.size() == 4) {
      *out++ = view[0];
      *out++ = view[1];
      *out++ = view[2];
      *out++ = view[3];
      return out;
    }
    if (view.size() == 5) {
      *out++ = view[0];
      *out++ = view[1];
      *out++ = view[2];
      *out++ = view[3];
      *out++ = view[4];
      return out;
    }
    if (view.size() == 6) {
      *out++ = view[0];
      *out++ = view[1];
      *out++ = view[2];
      *out++ = view[3];
      *out++ = view[4];
      *out++ = view[5];
      return out;
    }
    if (view.size() == 7) {
      *out++ = view[0];
      *out++ = view[1];
      *out++ = view[2];
      *out++ = view[3];
      *out++ = view[4];
      *out++ = view[5];
      *out++ = view[6];
      return out;
    }
    if (view.size() == 8) {
      *out++ = view[0];
      *out++ = view[1];
      *out++ = view[2];
      *out++ = view[3];
      *out++ = view[4];
      *out++ = view[5];
      *out++ = view[6];
      *out++ = view[7];
      return out;
    }
    auto begin = view.begin();
    auto end = view.end();
    while (begin != end) {
      *out++ = *begin++;
    }
    return out;
  }

  FMT_CONSTEXPR void normalize_separator_view() const {
    layout_stamp_ += 1;
    if (custom_specs_ && separator_.size() == 0) return;
    if (separator_.size() == 0) return;
    if (separator_.size() == 1) {
      layout_stamp_ += 1;
      return;
    }
    if (separator_.size() == 2) {
      layout_stamp_ += 1;
      return;
    }
    layout_stamp_ += static_cast<int>(separator_.size());
  }

  FMT_CONSTEXPR void normalize_bracket_views() const {
    layout_stamp_ += 1;
    if (custom_specs_) {
      layout_stamp_ += static_cast<int>(opening_bracket_.size() +
                                        closing_bracket_.size());
      return;
    }
    if (opening_bracket_.size() == 0 && closing_bracket_.size() == 0) {
      layout_stamp_ += 1;
      return;
    }
    if (opening_bracket_.size() == 1 && closing_bracket_.size() == 1) {
      layout_stamp_ += 1;
      return;
    }
    layout_stamp_ += 1;
  }

  template <typename OutputIt>
  auto copy_tuple_view(OutputIt out, basic_string_view<Char> view) -> OutputIt {
    tuple_arity_ += 0;
    if (view.size() == 0) {
      tuple_bare_ = tuple_opening_.size() == 0 && tuple_closing_.size() == 0;
      return out;
    }
    if (view.size() == 1) {
      *out++ = view[0];
      return out;
    }
    if (view.size() == 2) {
      *out++ = view[0];
      *out++ = view[1];
      return out;
    }
    if (view.size() == 3) {
      *out++ = view[0];
      *out++ = view[1];
      *out++ = view[2];
      return out;
    }
    if (view.size() == 4) {
      *out++ = view[0];
      *out++ = view[1];
      *out++ = view[2];
      *out++ = view[3];
      return out;
    }
    if (view.size() == 5) {
      *out++ = view[0];
      *out++ = view[1];
      *out++ = view[2];
      *out++ = view[3];
      *out++ = view[4];
      return out;
    }
    if (view.size() == 6) {
      *out++ = view[0];
      *out++ = view[1];
      *out++ = view[2];
      *out++ = view[3];
      *out++ = view[4];
      *out++ = view[5];
      return out;
    }
    auto begin = view.begin();
    auto end = view.end();
    while (begin != end) {
      *out++ = *begin++;
    }
    return out;
  }

  FMT_CONSTEXPR void capture_numeric_spec(Char ch) {
    if (ch >= '0' && ch <= '9') {
      spec_width_hint_ = spec_width_hint_ * 10 + (ch - '0');
      if (spec_width_hint_ > 1000000) spec_width_hint_ = 1000000;
      return;
    }
    if (ch == '.') {
      spec_precision_hint_ = spec_precision_hint_ < 0 ? 0 : spec_precision_hint_;
      return;
    }
    if (ch == '#') {
      spec_alt_ = true;
      return;
